// server/services/ai/insights/insight-management.service.ts
// ================================
// Insight feed management: listing, de-duplication, and marking as read.
//
// The same signal can be generated by several sources (rule engine, AI
// provider, integration scans). The feed therefore collapses rows that share a
// fingerprint — or the same normalised title — and keeps the newest row so the
// AI Insights page never shows duplicates.
// ================================

import { prisma } from '../../../lib/prisma.js';

type InsightRow = {
  id: string;
  title: string;
  description?: string | null;
  type: string;
  impact: string;
  confidence: number;
  isRead: boolean;
  metadata?: unknown;
  createdAt: Date;
};

export function insightKey(row: { title: string; metadata?: unknown }): string {
  const fingerprint = (row.metadata as Record<string, unknown> | null)?.fingerprint;
  if (typeof fingerprint === 'string' && fingerprint.trim()) return `fp:${fingerprint.trim()}`;
  return `title:${row.title.trim().toLowerCase().replace(/\s+/g, ' ')}`;
}

/** Keep the newest row per key. Input must be ordered newest-first. */
export function dedupeInsights<T extends { title: string; metadata?: unknown }>(rows: T[]): T[] {
  const seen = new Set<string>();
  const out: T[] = [];
  for (const row of rows) {
    const key = insightKey(row);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(row);
  }
  return out;
}

/** Remove duplicate rows from the database, keeping the newest per key. */
export async function pruneDuplicateInsights(userId: string): Promise<number> {
  const rows = (await prisma.aIInsight.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    take: 300,
  })) as unknown as InsightRow[];

  const keep = new Set(dedupeInsights(rows).map((row) => row.id));
  const duplicates = rows.filter((row) => !keep.has(row.id)).map((row) => row.id);
  if (duplicates.length) {
    await prisma.aIInsight.deleteMany({ where: { id: { in: duplicates } } });
  }
  return duplicates.length;
}

// ---- List Insights (workspace-wide, permission-scoped) ----
export async function listInsights(userId: string, limit: number = 50): Promise<any> {
  const take = Math.min(300, Math.max(limit * 3, 60));
  const rows = (await prisma.aIInsight.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    take,
  })) as unknown as InsightRow[];

  return {
    success: true,
    data: dedupeInsights(rows).slice(0, limit),
  };
}

// ---- Mark Insight Read ----
export async function markInsightRead(userId: string, insightId: string): Promise<any> {
  const insight = await prisma.aIInsight.findFirst({ where: { id: insightId, userId } });
  if (!insight) {
    return { success: false, data: { error: 'Insight not found' } };
  }

  await prisma.aIInsight.update({
    where: { id: insightId },
    data: { isRead: true },
  });

  return {
    success: true,
    data: { id: insightId, isRead: true },
    message: 'Insight marked as read',
  };
}
